begin;select no_plan();
create temporary table meter_cfg as select '{"model":"gpt-6.1-sol","requestModel":"gpt-6.1-sol","responseModels":["gpt-6.1-sol"],"inputPerMillionNano":"10000000000","cachedInputPerMillionNano":"1000000000","cacheWritePerMillionNano":"12500000000","outputPerMillionNano":"50000000000","markupBps":10000,"maxInputTokens":32000,"maxOutputTokens":1000,"evidence":"Synthetic offline values, no approved live pricing","meteringVersion":2,"serviceTier":"default","cacheTtl":"30m"}'::jsonb c;
create temporary table meter_receipt as select '{"providerRequestId":"synthetic-r1","resolvedModel":"gpt-6.1-sol","finishReason":"stop","inputTokens":1000,"outputTokens":100,"cachedInputTokens":200,"cacheWriteTokens":300,"totalTokens":1100,"meteringVersion":2,"serviceTier":"default","cacheTtl":"30m"}'::jsonb r;
select is(private.chat_usage_cap(c),90::bigint,'maximum cache write rate is reserved')from meter_cfg;
select is(private.chat_usage_amount(c,90,r)->>'costNano','13950000','input read and write are disjoint cost categories')from meter_cfg,meter_receipt;
select is(private.chat_usage_amount(c,90,r)->>'captureMinor','3','all usage rounds once at wallet precision')from meter_cfg,meter_receipt;
select is(private.chat_usage_amount(c,90,r)->>'releaseMinor','87','unused maximum is returned')from meter_cfg,meter_receipt;
select is(private.chat_usage_amount(c,90,r-'cacheWriteTokens')->>'pendingMinor','90','missing write evidence stays held')from meter_cfg,meter_receipt;
select is(private.chat_usage_amount(c,90,jsonb_set(r,'{serviceTier}','"priority"'))->>'pendingMinor','90','tier mismatch stays held')from meter_cfg,meter_receipt;
select is(private.chat_usage_amount(c,90,jsonb_set(r,'{cacheWriteTokens}','801'))->>'pendingMinor','90','overlapping input counters stay held')from meter_cfg,meter_receipt;
insert into private.chat_usage_versions(version,tariff)select 'synthetic-metering-legacy',c-'meteringVersion'-'serviceTier'-'cacheTtl'-'cacheWritePerMillionNano'from meter_cfg;
update private.chat_usage_settings set enabled=true,version='synthetic-metering-legacy'where model='gpt-6.1-sol';
select throws_ok($$select private.chat_usage_config('gpt-6.1-sol')$$,'P0001','invalid_metering_profile','new OpenAI calls require a complete versioned profile');
select is(private.chat_usage_amount(c-'meteringVersion'-'serviceTier'-'cacheTtl'-'cacheWritePerMillionNano',74,r-'meteringVersion'-'serviceTier'-'cacheTtl'-'cacheWriteTokens')->>'costNano','13200000','legacy snapshots retain their original math')from meter_cfg,meter_receipt;
select ok(not has_function_privilege('anon','public.chat_usage_dispatch(uuid,text,jsonb)','execute')and not has_function_privilege('authenticated','public.openai_chat_relay(uuid,uuid,text,text,text)','execute'),'metering adds no browser management permission');
create temporary table ark_meter_cfg as select (c-'cacheTtl'-'cacheWritePerMillionNano')||'{"model":"doubao","meteringVersion":3,"requestModel":"frozen-ark","responseModels":["frozen-ark"],"inputPerMillionNano":"800000000","cachedInputPerMillionNano":"160000000","outputPerMillionNano":"2700000000","maxOutputTokens":4000}'::jsonb c from meter_cfg;
create temporary table ark_meter_receipt as select (r-'cacheTtl'-'cacheWriteTokens')||'{"resolvedModel":"frozen-ark","meteringVersion":3,"outputTokens":500,"totalTokens":1500}'::jsonb r from meter_receipt;
select is(private.chat_usage_cap(c),8::bigint,'Ark regular budget has no OpenAI write uplift')from ark_meter_cfg;
select is(private.chat_usage_amount(c,8,r)->>'costNano','2022000','Ark input cache and output match domain')from ark_meter_cfg,ark_meter_receipt;
select is(private.chat_usage_amount(c,8,r)->>'releaseMinor','7','Ark actual token difference is returned')from ark_meter_cfg,ark_meter_receipt;
select is(private.chat_usage_amount(c,8,jsonb_set(r,'{serviceTier}','"fast"'))->>'pendingMinor','8','Ark actual fast tier cannot select regular pricing')from ark_meter_cfg,ark_meter_receipt;
select is(private.chat_usage_amount(c,8,r-'serviceTier')->>'pendingMinor','8','Ark missing actual tier is held')from ark_meter_cfg,ark_meter_receipt;
insert into private.chat_usage_versions(version,tariff)select 'synthetic-ark-3',c from ark_meter_cfg;
update private.chat_usage_settings set enabled=true,version='synthetic-ark-3'where model='doubao';
select is(private.chat_usage_config('doubao')->>'meteringVersion','3','new Ark tariff config validates its independent profile');
select finish();rollback;
